<?php
namespace App\Http\Controllers; use App\Models\{Item,Sale,Purchase,Expense}; use Illuminate\Support\Facades\DB; use Illuminate\Http\Request;
class DashboardController extends Controller {public function index(Request $r){$from=$r->input('from',now()->startOfMonth()->toDateString());$to=$r->input('to',now()->toDateString());$sales=Sale::whereBetween('sale_date',[$from,$to]);$purchases=Purchase::whereBetween('purchase_date',[$from,$to]);$expenses=Expense::whereBetween('expense_date',[$from,$to]);return view('dashboard',['from'=>$from,'to'=>$to,'todaySale'=>Sale::whereDate('sale_date',today())->sum('total'),'monthSale'=>Sale::whereMonth('sale_date',now()->month)->whereYear('sale_date',now()->year)->sum('total'),'rangeSale'=>(clone $sales)->sum('total'),'rangePurchases'=>(clone $purchases)->sum('total'),'rangeExpenses'=>(clone $expenses)->sum('amount'),'stockValue'=>Item::selectRaw('COALESCE(SUM(quantity * buying_price),0) as value')->value('value'),'itemsCount'=>Item::count(),'lowStock'=>Item::whereColumn('quantity','<=','low_stock_limit')->orderBy('quantity')->take(8)->get(),'recentSales'=>Sale::latest('sale_date')->take(8)->get(),'saleDue'=>DB::table('sales')->selectRaw('COALESCE(SUM(total-paid_amount),0) as due')->value('due'),'purchaseDue'=>DB::table('purchases')->selectRaw('COALESCE(SUM(total-paid_amount),0) as due')->value('due')]);}}
